int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t *num_pairs) {
    if (!in || !keys_out || !vals_out || !num_pairs) return -1;

    size_t count = 0;
    const char *start = in;
    while (*start != '\0') {
        const char *eq = strchr(start, '=');
        if (!eq) break;
        count++;
        start = eq + 1;
    }

    *keys_out = malloc(count * sizeof(char *));
    *vals_out = malloc(count * sizeof(char *));
    if (!*keys_out || !*vals_out) {
        free(*keys_out);
        free(*vals_out);
        return -1;
    }

    start = in;
    for (size_t i = 0; i < count; i++) {
        const char *eq = strchr(start, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - start);
        (*keys_out)[i] = malloc(klen + 1);
        if (!(*keys_out)[i]) {
            for (size_t j = 0; j < i; j++) {
                free((*keys_out)[j]);
            }
            free(*keys_out);
            free(*vals_out);
            return -1;
        }
        strncpy((*keys_out)[i], start, klen);
        (*keys_out)[i][klen] = '\0';

        const char *val_start = eq + 1;
        if (*val_start == '"') {
            const char *quote_end = strchr(val_start + 1, '"');
            if (quote_end) {
                size_t vlen = (size_t)(quote_end - val_start - 1);
                (*vals_out)[i] = malloc(vlen + 1);
                if (!(*vals_out)[i]) {
                    for (size_t j = 0; j <= i; j++) {
                        free((*keys_out)[j]);
                        free((*vals_out)[j]);
                    }
                    free(*keys_out);
                    free(*vals_out);
                    return -1;
                }
                strncpy((*vals_out)[i], val_start + 1, vlen);
                (*vals_out)[i][vlen] = '\0';
                start = quote_end + 1;
            } else {
                break;
            }
        } else {
            size_t vlen = 0;
            while (val_start[vlen] != '\0' && val_start[vlen] != ' ') {
                vlen++;
            }
            (*vals_out)[i] = malloc(vlen + 1);
            if (!(*vals_out)[i]) {
                for (size_t j = 0; j <= i; j++) {
                    free((*keys_out)[j]);
                    free((*vals_out)[j]);
                }
                free(*keys_out);
                free(*vals_out);
                return -1;
            }
            strncpy((*vals_out)[i], val_start, vlen);
            (*vals_out)[i][vlen] = '\0';
            start = val_start + vlen;
        }
    }

    *num_pairs = count;
    return 0;
}

